{
  "root": "main_stack",
  "state": {
    "budgetData": [
      {
        "Department": "R&D",
        "Hardware": 50000,
        "Software": 30000,
        "Personnel": 100000
      },
      {
        "Department": "Marketing",
        "Hardware": 10000,
        "Software": 20000,
        "Personnel": 70000
      },
      {
        "Department": "Operations",
        "Hardware": 20000,
        "Software": 15000,
        "Personnel": 80000
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_text",
        "description_text",
        "budget_summary_card",
        "budget_table_card"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Project Budget Allocation Overview",
        "variant": "h2"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "This section details the budget allocation for each department, categorized by Hardware, Software, and Personnel costs."
      },
      "children": []
    },
    "budget_summary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "summary_title",
        "total_hardware_text",
        "total_software_text",
        "total_personnel_text"
      ]
    },
    "summary_title": {
      "type": "Text",
      "props": {
        "text": "Total Budget Summary",
        "variant": "h3"
      },
      "children": []
    },
    "total_hardware_text": {
      "type": "Text",
      "props": {
        "text": "Total Hardware: $80,000",
        "variant": "body"
      },
      "children": []
    },
    "total_software_text": {
      "type": "Text",
      "props": {
        "text": "Total Software: $65,000",
        "variant": "body"
      },
      "children": []
    },
    "total_personnel_text": {
      "type": "Text",
      "props": {
        "text": "Total Personnel: $250,000",
        "variant": "body"
      },
      "children": []
    },
    "budget_table_card": {
      "type": "Card",
      "props": {},
      "children": [
        "budget_table_title",
        "budget_table"
      ]
    },
    "budget_table_title": {
      "type": "Text",
      "props": {
        "text": "Departmental Budget Allocation",
        "variant": "h3"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "statePath": "/budgetData",
        "columns": [
          {
            "key": "Department",
            "label": "Department"
          },
          {
            "key": "Hardware",
            "label": "Hardware"
          },
          {
            "key": "Software",
            "label": "Software"
          },
          {
            "key": "Personnel",
            "label": "Personnel"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "Department",
        "numericColumns": [
          "Hardware",
          "Software",
          "Personnel"
        ]
      },
      "children": []
    }
  }
}
